mapper.select:
SELECT
TRIP_ID, USER_ID, TRIP_NAME, START_DATE, END_DATE,
IS_AI_ROUTE, SHARE_CODE, CREATED_AT, UPDATED_AT
FROM TRIP
WHERE TRIP_ID = #{tripId}
AND USER_ID = #{userId}

mapper.insert:
INSERT INTO TRIP (
USER_ID, TRIP_NAME, START_DATE, END_DATE, IS_AI_ROUTE, SHARE_CODE
) VALUES (
#{userId}, #{tripName}, #{startDate}, #{endDate}, #{isAiRoute}, #{shareCode}
)

INSERT INTO TRIP_DETAIL (
    TRIP_ID
    , CONTENT_ID
    , CONTENT_TYPE_ID
    , TITLE
    , TEL
    , LC_LS_SYSTM1
    , LC_LS_SYSTM2
    , LC_LS_SYSTM3
    , LC_LS_SYSTM1_NM
    , LC_LS_SYSTM2_NM
    , LC_LS_SYSTM3_NM
    , ZIPCODE
    , ADDR1
    , ADDR2
    , L_DONG_REGN_CD
    , L_DONG_SIGNGU_CD
    , MAPX
    , MAPY
    , VISIT_ORDER
    , VISIT_DATE
    , FIRSTIMAGE
) VALUES (
    #{tripId}
    , #{contentid}
    , #{contenttypeid}
    , #{title}
    , #{tel}
    , #{lclsSystm1}
    , #{lclsSystm2}
    , #{lclsSystm3}
    , #{lclsSystm1Nm}
    , #{lclsSystm2Nm}
    , #{lclsSystm3Nm}
    , #{zipcode}
    , #{addr1}
    , #{addr2}
    , #{ldongRegnCd}
    , #{ldongSignguCd}
    , #{mapx}
    , #{mapy}
    , #{visitOrder}
    , #{visitDate}
    , #{firstimage}
)

mapper.update:
UPDATE TRIP_DETAIL SET
    CONTENT_ID = #{contentid}
    CONTENT_TYPE_ID = #{contenttypeid}
    TITLE = #{title}
    TEL = #{tel}
    LC_LS_SYSTM1 = #{lclsSystm1}
    LC_LS_SYSTM2 = #{lclsSystm2}
    LC_LS_SYSTM3 = #{lclsSystm3}
    LC_LS_SYSTM1_NM = #{lclsSystm1Nm}
    LC_LS_SYSTM2_NM = #{lclsSystm2Nm}
    LC_LS_SYSTM3_NM = #{lclsSystm3Nm}
    ZIPCODE = #{zipcode}
    ADDR1 = #{addr1}
    ADDR2 = #{addr2}
    L_DONG_REGN_CD = #{ldongRegnCd}
    L_DONG_SIGNGU_CD = #{ldongSignguCd}
    MAPX = #{mapx}
    MAPY = #{mapy}
    VISIT_ORDER = #{visitOrder}
    VISIT_DATE = #{visitDate}
    FIRSTIMAGE  #{firstimage}
WHERE DETAIL_ID = #{detailId}
